  try{await recoverWrite(userKey.current,{state:stateRef.current,revision:revision.current,pending:target!==savedGeneration.current}).catch(()=>{});await saveCheckpoint({flush:cloudSave,acknowledged:()=>savedGeneration.current>=target,blocked:()=>!ready.current?'The workspace is still loading.':blocked.current?saveFailure.current||'Resolve the save conflict before saving.':recoverBlock.current?'Choose which recovered writing to keep before saving.':'',inFlight:()=>inflight.current,lastError:()=>saveFailure.current});notify('Saved in this browser.');}
