 function deleteTrash(ids?:string[]){
  if(!project)return;const candidates=ids?project.nodes.filter(n=>ids.includes(n.id)&&inTrash(project,n)&&!n.role):project.nodes.filter(n=>inTrash(project,n)&&!n.role);if(!candidates.length){notify(ids?'Choose a document in Trash first.':'Trash is empty.');return;}
  const count=new Set(candidates.flatMap(n=>[n.id,...descendants(project,n.id).map(x=>x.id)])).size;
  if(!window.confirm('Permanently delete '+count+' item(s) and their saved snapshots from this world? This cannot be undone. Unused uploaded files will also be removed.'))return;
  const removed=new Set<string>();changeProject((p,w)=>permanentDelete(w,p,candidates.map(n=>n.id)).forEach(id=>removed.add(id)));
  undoStack.current=[];redoStack.current=[];activeEditor.current=null;range.current=null;setTabs(t=>t.filter(id=>!removed.has(id)));if(removed.has(splitId))setSplitId('');setSelectedId(project.nodes.find(n=>n.role==='trash')!.id);setMode('corkboard');notify('Deleted permanently. Unused file cleanup runs after saving.');
 }
 useEffect(()=>{
  if(!loaded||status!=='saved'||!workspace.pendingAssetDeletes?.length)return;
  let cancelled=false;const cleanup=async()=>{if(cleanupLock.current||generation.current!==savedGeneration.current||blocked.current||recoverBlock.current)return;cleanupLock.current=true;const done:string[]=[];try{for(const id of stateRef.current.pendingAssetDeletes||[]){if(cancelled)break;try{const response=await fetch('/api/assets/'+id,{method:'DELETE'});if(response.ok||response.status===404||response.status===409)done.push(id);}catch{break;}}if(!cancelled&&done.length)update(w=>w.pendingAssetDeletes=(w.pendingAssetDeletes||[]).filter(id=>!done.includes(id)));}finally{cleanupLock.current=false;}};
  void cleanup();const timer=setInterval(()=>void cleanup(),30000);window.addEventListener('online',cleanup);return()=>{cancelled=true;clearInterval(timer);window.removeEventListener('online',cleanup);};
 },[loaded,status,workspace.pendingAssetDeletes?.join(',')]);
