 function command(cmd:string,value?:string){const a=activeEditor.current;if(a?.tiptap){const e=a.tiptap;if(e.isDestroyed){activeEditor.current=null;notify('Click inside the document to continue editing');return;}if(cmd==='bold')e.chain().focus().toggleBold().run();else if(cmd==='italic')e.chain().focus().toggleItalic().run();else if(cmd==='underline')e.chain().focus().toggleUnderline().run();else if(cmd==='undo')e.chain().focus().undo().run();else if(cmd==='redo')e.chain().focus().redo().run();else if(cmd==='insertText')e.chain().focus().insertContent(value||'').run();return;}if(!a){notify('Click inside a document first');return;}a.el.focus();if(range.current&&a.el.contains(range.current.commonAncestorContainer)){const s=window.getSelection();s?.removeAllRanges();s?.addRange(range.current);}document.execCommand(cmd,false,value);patch(a.id,{html:sanitize(a.el.innerHTML)});selection();}
