 function recoverDevice(){if(!recovery)return;recoverBlock.current=false;if(recovery.revision===revision.current){update(s=>Object.assign(s,recovery.state),true);switchProject(recovery.state.projects.find(p=>!p.archived)?.id||'');}else{update(s=>{for(const old of recovery.state.projects){const p=structuredClone(old),oldPid=p.id,map=new Map(p.nodes.map(n=>[n.id,uid()]));p.id=uid();p.title+=' (Recovered)';if(p.activeDraftId)p.activeDraftId=map.get(p.activeDraftId);p.nodes.forEach(n=>{const origin=n.fields['revision.origin']||n.id;n.fields['revision.origin']=map.get(origin)||origin;n.id=map.get(n.id)!;n.parent=n.parent?map.get(n.parent)||null:null;for(const [oldId,newId] of map)n.html=n.html.split('data-profile-id="'+oldId+'"').join('data-profile-id="'+newId+'"');if(n.previousParent)n.previousParent=map.get(n.previousParent)||null;n.bookmarks.forEach(b=>{if(b.url.startsWith('#document:'))b.url='#document:'+(map.get(b.url.slice(10))||b.url.slice(10));});});p.moodboard?.forEach(c=>{c.id=uid();c.profileIds=c.profileIds?.map(id=>map.get(id)||id);if(c.notesHtml)for(const [oldId,newId] of map)c.notesHtml=c.notesHtml.split('data-profile-id="'+oldId+'"').join('data-profile-id="'+newId+'"');if(c.sceneId){const slash=c.sceneId.indexOf('/');c.sceneId=(map.get(c.sceneId.slice(0,slash))||c.sceneId.slice(0,slash))+c.sceneId.slice(slash);}});remapVisualDocuments(p,map);if(p.sceneBeats)p.sceneBeats=Object.fromEntries(Object.entries(p.sceneBeats).map(([id,meta])=>{const slash=id.indexOf('/');return [(map.get(id.slice(0,slash))||id.slice(0,slash))+id.slice(slash),{...meta,characters:meta.characters?.map(id=>map.get(id)||id),props:meta.props?.map(id=>map.get(id)||id),location:meta.location?map.get(meta.location)||meta.location:undefined}];}));p.beatOrders=undefined;p.collections.forEach(c=>{c.id=uid();c.ids=c.ids.map(id=>map.get(id)||id);});s.projects.push(p);s.history[p.id]=structuredClone(recovery.state.history[oldPid]||{});for(const snap of recovery.state.snapshots.filter(x=>x.projectId===oldPid))s.snapshots.push({...snap,id:uid(),projectId:p.id,nodeId:map.get(snap.nodeId)||snap.nodeId});}if(recovery.state.scratch)s.scratch+='\n\nRecovered notes\n'+recovery.state.scratch;},true);}setRecovery(null);setModal(null);notify('Device writing recovered');}
